import { md5 } from 'js-md5';
import { namespaces as ns } from '@entryscape/rdfjson';

const HASH_LEN = 8;
const CURIE_RE = /^[a-zA-Z][\w-]*:[^/]/;
const seen = new Map();

const expand = (p) => {
  const out = ns.expand(p);
  if (out === p && CURIE_RE.test(p)) {
    console.warn(
      `hashAnchor: CURIE '${p}' could not be expanded — namespace not registered yet`
    );
  }
  return out;
};

/**
 * Build a short, stable anchor id from one or more URIs or CURIEs.
 *
 * External consumers may reproduce these fragments independently, so the
 * algorithm below is a contract — changing any step invalidates every
 * published deep link:
 *
 * 1. Each part is expanded to a full URI via `ns.expand()`.
 * 2. Falsy parts are kept as empty positional slots (`''`), never dropped, so
 *    `hashAnchor(p, undefined, x)` and `hashAnchor(p, x)` stay distinct.
 * 3. The parts are joined with `'|'`.
 * 4. The result is `` `${prefix}-${md5(input).slice(0, HASH_LEN)}` ``.
 *
 * Examples:
 *
 *   hashAnchor('ns', 'http://example.com/ns-document')
 *     -> 'ns-' + md5('http://example.com/ns-document').slice(0, 8)
 *     -> 'ns-88eabfef'
 *
 *   hashAnchor('ps', 'http://example.com/ns-document', 'dcterms:title')
 *     -> 'ps-' + md5('http://example.com/ns-document|http://purl.org/dc/terms/title').slice(0, 8)
 *     -> 'ps-bf22f997'
 *
 * @param {string} prefix anchor namespace, e.g. 'ns', 'ps', 'rclass', 'rprop'
 * @param {...(string|undefined)} parts URIs or CURIEs, positionally significant
 * @returns {string} the anchor id
 */
const hashAnchor = (prefix, ...parts) => {
  const input = parts.map((p) => (p ? expand(p) : '')).join('|');
  const id = `${prefix}-${md5(input).slice(0, HASH_LEN)}`;
  const prior = seen.get(id);
  if (prior !== undefined && prior !== input) {
    console.warn(
      `hashAnchor collision: '${id}' produced by both '${prior}' and '${input}'`
    );
  } else {
    seen.set(id, input);
  }
  return id;
};

export { hashAnchor };
