import { namespaces as ns } from '@entryscape/rdfjson';

const getConstraint = (item, property, asArray) => {
  const constraints = item.getConstraints();
  if (constraints) {
    const constraintValue =
      constraints[property] || constraints[ns.expand(property)];
    if (Array.isArray(constraintValue)) {
      if (asArray) {
        return constraintValue.map((cv) => ns.expand(cv));
      }
      return ns.expand(constraintValue[0]);
    }
    if (constraintValue) {
      if (asArray) {
        return [ns.expand(constraintValue)];
      }
      return ns.expand(constraintValue);
    }
  }
  return undefined;
};

const getConstrType = (item, asArray = false) => {
  return getConstraint(item, 'rdf:type', asArray);
};

const getConstraintInScheme = (item, asArray = false) => {
  return getConstraint(item, 'skos:inScheme', asArray);
};

const getLabel = (item) => {
  let label = item.getLabel();
  if (!label) {
    label = getConstrType(item);
    if (label) {
      label = ns.shortenKnown(label);
    }
  }
  if (!label) {
    label = item.getId();
  }
  return label;
};

export { getConstrType, getConstraintInScheme, getLabel };
