import rdforms from '@entryscape/rdforms';
import {
  NAMESPACE_SHACL,
  RDF_TYPE_NODESHAPE,
  RDF_TYPE_PROPERTYSHAPE,
  RDF_LANGSTRING,
  RDF_TYPE_ONTOLOGY,
  SH_IRI,
  SH_LITERAL,
  SH_BLANK,
  SH_BLANK_OR_IRI,
  SH_TARGET_CLASS,
  SH_CLASS,
  SH_DECLARE,
  SH_PREFIX,
  SH_NAMESPACE,
  SKOS_SCOPENOTE
} from './NS.js';
import {namespaces} from "@entryscape/rdfjson";


const extractExtends = (graph, uri) => {
  const andListNode = graph.findFirstValue(uri, 'sh:and');
  if (andListNode) {
    const andList = graph.getList(andListNode);
    if (andList.length > 0) {
      return andList[0].value;
    }
  }
};

const _extractFilteredNodeConstraint = (graph, uri, isBlank) => {
  const shNode = graph.findFirstValue(uri, 'sh:node');
  const shNodeIsBlank = graph.find(shNode)[0].isSubjectBlank();
  return shNodeIsBlank === isBlank ? shNode : null;
};

const _extractRdfTypeConstraint = (graph, uri) => {
  const constraints = []
  graph.find(uri, 'sh:property').forEach(stmt => {
    const ps = stmt.getValue();
    const path = graph.findFirstValue(ps, 'sh:path');
    if (path === namespaces.expand('rdf:type')) {
      const inNode = graph.findFirstValue(ps, 'sh:in');
      if (inNode) {
        graph.getList(inNode).forEach(o => constraints.push(o.value));
      }
    }
  });
  if (constraints.length > 1) {
    return constraints;
  }
  if (constraints.length === 1) {
    return constraints[0];
  }
};

const extractConstraints = (graph, uri) => {
  const targetClass = graph.findFirstValue(uri, SH_TARGET_CLASS); // implies a class constraint
  const shClass = graph.findFirstValue(uri, SH_CLASS); // allowed on PropertyShapes
  const rdfTypeProperty = _extractRdfTypeConstraint(graph, uri);

  const constr = {};
  if (targetClass || shClass || rdfTypeProperty) {
    constr[namespaces.expand('rdf:type')] = targetClass || shClass || rdfTypeProperty;
    return constr;
  }

  const shNode = _extractFilteredNodeConstraint(graph, uri, true);
  if (shNode) {
    graph.find(shNode, 'sh:property').forEach(stmt => {
      const ps = stmt.getValue();
      const path = graph.findFirstValue(ps, 'sh:path');
      const value = graph.findFirstValue(ps, 'sh:hasValue');
      if (value) {
        constr[path] = value;
      } else {
        const inNode = graph.findFirstValue(ps, 'sh:in');
        if (inNode) {
          const inList = graph.getList(inNode);
          if (inList.length > 0) {
            constr[path] = inList.map(o => o.value);
          }
        }
      }
    });
  }
  if (Object.keys(constr).length > 0) {
    return constr;
  }
};

const extractNumber = (value) => {
  const parsed = parseInt(value);
  if (isNaN(parsed)) {
    return undefined;
  }
  return parsed;
}

const extractCardinality = (graph, uri) => {
  let min = extractNumber(graph.findFirstValue(uri, 'sh:minCount'));
  const max = extractNumber(graph.findFirstValue(uri, 'sh:maxCount'));
  const pref = min === 0 || min === undefined ? 1 : undefined;
  if (min === -1 || min === undefined) {
    min = 0;
  }
  return {min, pref, max};
};

const extractNodeKind = (graph, uri) => {
  const nodeKind = graph.findFirstValue(uri, 'sh:nodeKind');
  const datatype = graph.findFirstValue(uri, 'sh:datatype');
  switch (nodeKind) {
    case SH_BLANK:
      return 'BLANK';
    case SH_IRI:
      return 'URI';
    case SH_BLANK_OR_IRI:
      return 'RESOURCE';
    case SH_LITERAL:
      if (datatype === RDF_LANGSTRING) {
        return 'LANGUAGE_LITERAL';
      } else if (datatype) {
        return 'DATATYPE_LITERAL';
      }
      return 'LITERAL';
    default:
      if (datatype) {
        return 'DATATYPE_LITERAL';
      }
  }
};

const extractDatatype = (graph, uri) => {
  const datatype = graph.findFirstValue(uri, 'sh:datatype');
  if (datatype && datatype != RDF_LANGSTRING) {
    return datatype;
  }
}

const extractTexts = (graph, uri) => {
  let isversionof = graph.findFirstValue(uri, 'dcterms:isVersionOf');
  const usageNote = rdforms.utils.getLocalizedMap(graph, uri, [SKOS_SCOPENOTE]);
  if (!usageNote && !isversionof) {
    return;
  }

  const text = { };
  if (usageNote) {
    text.usageNote = usageNote;
  }
  if (isversionof) {
    text.isversionof = {'': isversionof};
  }
  return text;
}

const extractItems = (graph, uri) => {
  const itemObjs = graph.find(uri, 'sh:property').map(stmt => {
    const resource = stmt.getValue();
    const obj = {resource, blank: stmt.isObjectBlank()};
    obj.path = graph.findFirstValue(resource, 'sh:path');
    obj.order = graph.findFirstValue(resource, 'sh:order');
    obj.order = parseInt(obj.order);
    if (obj.order === NaN) {
      delete obj.order
    }
    if (obj.blank) {
      obj.extends = extractExtends(graph, resource);
      if (!obj.extends) return null;
    }
    return obj;
  }).filter(o => o);
  const explicitOrder = itemObjs.filter(it => it.order !== undefined);
  const pathOrder = itemObjs.filter(it => it.order === undefined);
  explicitOrder.sort((a, b) => a.order > b.order ? 1 : -1);
  pathOrder.sort((a, b) => a.path > b.path ? 1 : -1);
  return explicitOrder.concat(pathOrder).map(obj => {
    if (obj.blank) {
      return obj.extends;
    } else {
      return obj.resource;
    }
  });
}

const extractChoices = (graph, uri) => {
  const choicesNode = graph.findFirstValue(uri, 'sh:in');
  if (choicesNode) {
    const choiceList = graph.getList(choicesNode);
    if (choiceList.length > 0) {
      if (choiceList[0].type === 'uri') {
        // TODO extract better labels.
        return {choices: choiceList.map(o => ({ value: o.value })), choiceType: 'URI'};
      } else {
        return {choices: choiceList.map(o => ({ value: o.value })), choiceType: 'LITERAL'};
      }
    }
  }
  return {choices: undefined, choiceType: undefined};
};

const extractNodeShape = (graph, uri) => {
  const obj = {
    id: uri,
    extends: extractExtends(graph, uri),
    type: 'group',
    label: rdforms.utils.getLocalizedMap(graph, uri, ['sh:name']),
    description: rdforms.utils.getLocalizedMap(graph, uri, ['sh:description']),
    constraints: extractConstraints(graph, uri),
    nodetype: extractNodeKind(graph, uri),
    datatype: extractDatatype(graph, uri),
    text: extractTexts(graph, uri),
    items: extractItems(graph, uri),
  };
  return obj;
};

const extractRootNode = (rootNodes, graph, uri) => {
  const targetClass = graph.findFirstValue(uri, SH_TARGET_CLASS);
  if (targetClass) {
    rootNodes.push(uri);
  }
};

const extractPropertyShape = (graph, uri) => {
  const obj = {
    id: uri,
    extends: extractExtends(graph, uri),
    type: 'text', // may be overridden later
    property: graph.findFirstValue(uri, 'sh:path'),
    label: rdforms.utils.getLocalizedMap(graph, uri, ['sh:name']),
    description: rdforms.utils.getLocalizedMap(graph, uri, ['sh:description']),
    constraints: extractConstraints(graph, uri),
    nodetype: extractNodeKind(graph, uri),
    datatype: extractDatatype(graph, uri),
    pattern: graph.findFirstValue(uri, 'sh:pattern'),
    text: extractTexts(graph, uri),
    cardinality: extractCardinality(graph, uri)
  };

  const {choices, choiceType} = extractChoices(graph, uri);
  // item is a choice
  if (choices) {
    obj.type = 'choice';
    obj.choices = choices;
    obj.nodetype = obj.nodetype || choiceType;
  }
  if (obj.constraints) {
    obj.type = 'choice';
    obj.nodetype = 'URI';
  }

  const shNode = _extractFilteredNodeConstraint(graph, uri, false);
  if (obj.extends === undefined && shNode) {
    // item corresponds to an inline field
    obj.extends = shNode;
    obj.type = 'group';
  }

  return obj;
};

const extractPrefixedNamespaces = (graph) => {
  const baseNode = graph.subjects('rdf:type', RDF_TYPE_ONTOLOGY).constr('owl:imports', NAMESPACE_SHACL)[0];
  const prefixes = {};
  graph.find(baseNode, SH_DECLARE, null).forEach(stmt => {
    const ps = stmt.getValue();
    const prefix = graph.findFirstValue(ps, SH_PREFIX);
    const namespace = graph.findFirstValue(ps, SH_NAMESPACE);
    prefixes[prefix] = namespace;
  });
  return prefixes;
}

const sortTemplates = (templates) => {
  const arr = [];
  const added = new Set();
  let remains = templates;
  while (remains.length > 0) {
    const newRemains = [];
    for (let t of remains) {
      const ext = t.extends;
      if (!ext || added.has(ext)) {
        arr.push(t);
        added.add(t.id);
      } else {
        newRemains.push(t);
      }
    }
    remains = newRemains;
  }
  return arr;
};

export default (itemstore, graph) => {
  const nodeshapes = graph.subjects('rdf:type', RDF_TYPE_NODESHAPE).values('uri');
  const propertyshapes = graph.subjects('rdf:type', RDF_TYPE_PROPERTYSHAPE).values('uri');
  const unOrderedTemplates = [];
  const rootNodes = [];
  propertyshapes.forEach(uri =>
    unOrderedTemplates.push(extractPropertyShape(graph, uri)));
  nodeshapes.forEach(uri => {
    unOrderedTemplates.push(extractNodeShape(graph, uri));
    extractRootNode(rootNodes, graph, uri);
  });
  const dirtyTemplates = sortTemplates(unOrderedTemplates);
  const templates = JSON.parse(JSON.stringify(dirtyTemplates));
  const nses = extractPrefixedNamespaces(graph);
  if (rootNodes.length > 0) {
    itemstore.registerBundle({ source: { templates, namespaces: nses, roots: rootNodes } });
  } else {
    itemstore.registerBundle({ source: { templates, namespaces: nses } });
  }
};
