import bundleLoader from '@entryscape/rdforms/src/template/bundleLoader.js';
import ItemStore from '@entryscape/rdforms/src/template/ItemStore.js';
import { namespaces, Graph } from '@entryscape/rdfjson';
import shacl2rdforms from 'rdforms-shacl/src/shacl2rdforms.js';
import N3 from 'n3';
import { i18n } from 'esi18n';
import { renderForms } from './form.js';
import { renderNamespaces } from './namespaces.js';
import { renderVocabularies } from './vocab.js';
import { renderAppendixHeader } from './domUtils.js';
import mainTemplate from './main.html';
import navTemplate from './nav.html';
import specNLS from './nls/spec.nls';
import tocControlls from './tocControlls.js';
import '../assets/style.less';

const APPENDIX_ATTR = 'data-rdforms-appendix';
const RDF_TYPE_PROFILEFORM = 'https://rdforms.org/terms/ProfileForm';

// A top level class item, i.e. a candidate for the primary/supportive sections.
const isClassItem = (item) =>
  !!(
    item.getType() === 'group' &&
    !item.getProperty() &&
    item.getConstraints() &&
    item.getId()
  );

export default (config, nav, main) => {
  if (config.namespaces) {
    Object.keys(config.namespaces).forEach((ns) => {
      namespaces.add(ns, config.namespaces[ns]);
    });
  }
  if (config.language) {
    i18n.setLocale(config.language);
  }
  const itemStore = new ItemStore();
  let navNode = typeof nav === 'string' ? document.getElementById(nav) : nav;
  let mainNode =
    typeof main === 'string' ? document.getElementById(main) : main;
  if (!navNode) {
    navNode = document.getElementsByTagName('nav')[0];
    if (!navNode) {
      navNode = document.createElement('nav');
      document.body.appendChild(navNode);
    }
  }
  navNode.id = 'toc';
  if (!mainNode) {
    mainNode = document.getElementsByTagName('main')[0];
    if (!mainNode) {
      mainNode = document.createElement('main');
      document.body.appendChild(mainNode);
    }
  }
  let sectionNode;
  const sectionNodes = mainNode.querySelectorAll(
    `section:not([${APPENDIX_ATTR}])`
  );
  if (sectionNodes.length > 0) {
    sectionNode = sectionNodes[0];
  }

  let bundle = i18n.getLocalization(specNLS);
  if (Object.keys(bundle).length === 0) {
    bundle = bundle.__proto__;
  }
  navNode.innerHTML = i18n.renderNLSTemplate(navTemplate, bundle);
  mainNode.innerHTML = i18n.renderNLSTemplate(mainTemplate, bundle);

  const render = () => {
    if (config.title) {
      document.title = config.title;
      document.querySelectorAll('.rdforms-specs .title').forEach((el) => {
        el.textContent = config.title;
      });
    }
    if (config.introduction) {
      document.getElementById('introText').innerHTML = config.introduction;
    } else if (sectionNode) {
      document.getElementById('introText').appendChild(sectionNode);
    }
    const aps = document.getElementById('aps');
    const tocAps = document.getElementById('toc-aps');
    const sup = document.getElementById('sup');
    const tocSup = document.getElementById('toc-sup');

    // Only a section the caller left out is derived; a section given as an
    // explicitly empty array is honoured as-is, i.e. it renders no classes.
    // Hence the intent has to be captured before the defaults are applied.
    const hasMain = !!config.main;
    const hasSupportive = !!config.supportive;
    config.main = config.main || [];
    config.supportive = config.supportive || [];

    if (!hasMain && !hasSupportive) {
      const rootNodes = itemStore
        .getBundles()
        .map((bundle) => {
          return bundle._source.roots || [];
        })
        .flat();

      itemStore.getItems().forEach((item) => {
        if (isClassItem(item)) {
          if (
            item.getSource().about !== undefined &&
            item.getSource().about.rdfType.includes(RDF_TYPE_PROFILEFORM)
          ) {
            // determined based on form type if about.rdfType is available
            config.main.push(item.getId());
          } else if (rootNodes.includes(item.getId())) {
            // determined based on info from shacl-conversion
            config.main.push(item.getId());
          } else if (item.getNodetype() === 'URI') {
            // determined based on NodeType
            config.main.push(item.getId());
          } else {
            config.supportive.push(item.getId());
          }
        }
      });
    } else if (!hasMain) {
      itemStore.getItems().forEach((item) => {
        if (isClassItem(item) && !config.supportive.includes(item.getId())) {
          config.main.push(item.getId());
        }
      });
    } else if (!hasSupportive) {
      itemStore.getItems().forEach((item) => {
        if (isClassItem(item) && !config.main.includes(item.getId())) {
          config.supportive.push(item.getId());
        }
      });
    }
    renderForms(
      {
        items: config.main.map((id) => itemStore.getItem(id)),
        node: aps,
        nodeToc: tocAps,
      },
      {
        items: config.supportive.map((id) => itemStore.getItem(id)),
        node: sup,
        nodeToc: tocSup,
      },
      config.extras,
      config.getHREF
    );
    renderNamespaces(document.getElementById('nss'));
    renderVocabularies(
      document.getElementById('vocs'),
      document.getElementById('toc-vocabs')
    );
    const appendicies = document.querySelectorAll(`[${APPENDIX_ATTR}]`);
    if (appendicies.length > 0) {
      document.getElementById('toc-appendicies-li').style.display = null;
      document.getElementById('appendicies-content').style.display = null;
      const ixes = document.getElementById('ixes');
      const tocIxes = document.getElementById('toc-appendicies');
      appendicies.forEach((apx) => {
        const name = apx.getAttribute(APPENDIX_ATTR);
        renderAppendixHeader(name, ixes, tocIxes);
        ixes.appendChild(apx);
      });
    }
    if (typeof config.onDone === 'function') setTimeout(config.onDone, 1);
  };

  if (config.shacl) {
    fetch(config.shacl)
      .then((response) => response.text())
      .then((text) => {
        const parser = new N3.Parser();
        const quads = parser.parse(text);
        const graph = new Graph();
        graph.addQuads(quads);
        shacl2rdforms(itemStore, graph);
        render();
      });
  } else if (
    Array.isArray(config.bundles) &&
    config.bundles.length > 0 &&
    Array.isArray(config.bundles[0])
  ) {
    bundleLoader(itemStore, config.bundles, render);
  } else if (config.bundles) {
    config.bundles.forEach((b) => itemStore.registerBundle({ source: b }));
    render();
  } else if (config.bundle) {
    itemStore.registerBundle({ source: config.bundle });
    render();
  } else {
    console.log('No bundle configured.');
  }

  if (config.tocControlls !== false) {
    tocControlls();
  }
};
