import { namespaces as ns } from '@entryscape/rdfjson';
import utils from '@entryscape/rdforms/src/utils.js';
import { i18n } from 'esi18n';
import { getLabel, getConstrType, getConstraintInScheme } from './itemUtils.js';
import {
  createEl,
  addDef,
  addURIDef,
  renderHeader,
  renderSubHeader,
  initHeaderCounters,
} from './domUtils.js';
import { addVocabulary } from './vocab.js';
import { nsReg } from './namespaces.js';
import { hashAnchor } from './hashUtils.js';
import specNLS from './nls/spec.nls';

const NODE_SHAPE_PREFIX = 'ns';
const PROPERTY_SHAPE_PREFIX = 'ps';

const type2form = {};
const id2form = {};
let inlineFormCounter = 0;
let inline = [];

const findInlineObj = (item) => {
  const rdftype = getConstrType(item);
  const id = item.getId();
  if (rdftype) {
    return type2form[rdftype];
  } else if (id) {
    return id2form[id];
  }
  return inline.find((obj) => item === obj.item);
};

const indexForms = (items, supportive) => {
  items.forEach((item) => {
    const rdftype = getConstrType(item);
    const id = item.getId();
    let addedInline = false;
    if (rdftype) {
      type2form[rdftype] = {
        item,
        rdftype,
        label: getLabel(item),
        id: hashAnchor(NODE_SHAPE_PREFIX, id || rdftype),
      };
      if (supportive) {
        inline.push(type2form[rdftype]);
        addedInline = true;
      }
    }
    if (id) {
      id2form[id] = {
        item,
        label: getLabel(item),
        id: hashAnchor(NODE_SHAPE_PREFIX, id),
      };
      if (supportive && !addedInline) {
        inline.push(id2form[id]);
      }
    }

    const perChild = (childItem) => {
      if (childItem.getType() === 'group') {
        if (childItem.getProperty()) {
          const childRdftype = getConstrType(childItem);
          const childId = childItem.getId();
          let id;
          if (childRdftype || childId) {
            if (findInlineObj(childItem)) {
              return;
            }
            id = hashAnchor(NODE_SHAPE_PREFIX, childId || childRdftype);
          } else {
            inlineFormCounter += 1;
            id = `internal${inlineFormCounter}`;
          }
          const obj = {
            id,
            label: getLabel(childItem),
            item: childItem,
            rdftype: childRdftype,
          };
          inline.push(obj);
          if (childRdftype) {
            type2form[childRdftype] = obj;
          }
          if (childId) {
            id2form[childId] = obj;
          }
        } else {
          childItem.getChildren().forEach(perChild);
        }
      }
    };

    item.getChildren().forEach(perChild);
  });
};

let chapter;
const renderFormHeader = (item, node, toc, id) => {
  const obj = id2form[item.getId()] || type2form[getConstrType(item)];
  if (obj) {
    return renderHeader(chapter, obj.label, node, toc, obj.id);
  } else {
    return renderHeader(chapter, getLabel(item), node, toc, id);
  }
};

const idIdx = {};

const renderFieldHeader = (item, field, node, toc) => {
  const formInput = item.getId() || getConstrType(item) || item.extends();
  const fieldInput = field.getId() || field.getProperty();
  const dedupKey = `${formInput} ${fieldInput}`;
  let id = hashAnchor(PROPERTY_SHAPE_PREFIX, formInput, fieldInput);
  let nr = idIdx[dedupKey];
  if (nr !== undefined) {
    nr += 1;
    idIdx[dedupKey] = nr;
    id = `${id}-${nr}`;
  } else {
    idIdx[dedupKey] = 1;
  }
  return renderSubHeader(
    chapter,
    getLabel(item),
    getLabel(field),
    node,
    toc,
    id
  );
};

const getStringRange = (field) => {
  switch (field.getNodetype()) {
    case 'ONLY_LITERAL':
      return i18n.localize(specNLS, 'fieldLiteral', {});
    case 'LITERAL':
    case 'LANGUAGE_LITERAL':
      return i18n.localize(specNLS, 'fieldLangLit', {});
    case 'DATATYPE_LITERAL':
      let datatype = field.getDatatype();
      if (Array.isArray(datatype)) {
        datatype = datatype.map((d) => ns.shortenKnown(d)).join(', ');
      } else {
        datatype = ns.shortenKnown(datatype);
      }
      return i18n.localize(specNLS, 'fieldDatatype', { datatype });
    case 'URI':
      return i18n.localize(specNLS, 'fieldURI', {});
  }
};

const addTerminology = (inScheme, td, getHREF) => {
  inScheme.forEach((terminology, idx) => {
    if (idx !== 0) {
      createEl('span', ' | ', td);
    }
    const a = createEl('a', ns.shortenKnown(terminology), td);
    const href = getHREF ? getHREF(terminology, 'terminology') : terminology;
    a.setAttribute('href', href);
    a.setAttribute('target', 'blank');
  });
};

const addRange = (field, tbody, getHREF) => {
  const td = addDef(i18n.localize(specNLS, 'fieldRange', {}), '', tbody);
  switch (field.getType()) {
    case 'text':
      td.innerText = getStringRange(field);
      break;
    case 'choice': {
      const rdftype = getConstrType(field);
      const inScheme = getConstraintInScheme(field, true);
      if (field.hasChoices()) {
        addVocabulary(field, td);
      } else if (inScheme) {
        addTerminology(inScheme, td, getHREF);
      } else if (rdftype) {
        const obj = type2form[rdftype];
        if (obj) {
          const a = createEl('a', obj.label, td);
          a.setAttribute('href', `#${obj.id}`);
        } else {
          const a = createEl('a', rdftype, td);
          a.setAttribute('href', rdftype);
          a.setAttribute('target', 'blank');
        }
      }
      break;
    }
    case 'group': {
      const obj = findInlineObj(field);
      if (obj) {
        const a = createEl('a', obj.label, td);
        a.setAttribute('href', `#${obj.id}`);
      }
      break;
    }
  }
};

const renderFieldDetails = (field, node, extras, getHREF) => {
  const table = createEl('table', null, node);
  table.classList.add('propdef');
  table.classList.add('def');
  const tbody = createEl('tbody', null, table);
  addDef(i18n.localize(specNLS, 'fieldLabel', {}), `${getLabel(field)}`, tbody);
  const desc = field.getDescription();
  if (desc && desc != '') {
    addDef(i18n.localize(specNLS, 'fieldDescription', {}), desc, tbody, true);
  }
  addURIDef(
    i18n.localize(specNLS, 'fieldProperty', {}),
    ns.expand(field.getProperty()),
    tbody,
    getHREF
  );
  addRange(field, tbody, getHREF);
  const card = field.getCardinality() || {};
  const level = i18n.localize(specNLS, 'fieldLevel', {});
  if (card.min > 0) {
    addDef(level, i18n.localize(specNLS, 'levelMandatory', {}), tbody);
  } else if (card.pref > 0) {
    addDef(level, i18n.localize(specNLS, 'levelRecommended', {}), tbody);
  } else {
    addDef(level, i18n.localize(specNLS, 'levelOptional', {}), tbody);
  }
  const cardinality = i18n.localize(specNLS, 'fieldCardinality', {});
  const min = typeof card.min === 'number' ? card.min : 0;
  const max =
    typeof card.max === 'number'
      ? card.max
      : i18n.localize(specNLS, 'unlimited', {});
  if (min === max) {
    addDef(cardinality, `${min}`, tbody);
  } else {
    addDef(cardinality, `${min}..${max}`, tbody);
  }
  Object.keys(extras || {}).forEach((extraKey) => {
    // A label may be a ready-to-use string or a locale-keyed object; getLocalizedValue
    // resolves both, falling back from the active locale to English to any defined key.
    const extraLabel = utils.getLocalizedValue(extras[extraKey]).value;
    if (extraLabel == null) {
      console.warn(
        `Ignoring extra "${extraKey}": label must be a string or a locale-keyed object.`
      );
    }
    const textValue = field.getText(extraKey);
    if (textValue && extraLabel) {
      addDef(extraLabel, textValue, tbody, true);
    }
  });
};

const renderField = (item, node, field, tbody, tocOl, extras, getHREF) => {
  if (!field.hasStyle('deprecated')) {
    if (!field.getProperty()) {
      if (field.getType() === 'group') {
        field.getChildren().forEach((field2) => {
          renderField(item, node, field2, tbody, tocOl, undefined, getHREF);
        });
      }
    } else {
      const id = renderFieldHeader(item, field, node, tocOl);
      const tr = createEl('tr', null, tbody);
      const th = createEl('th', null, tr);
      createEl('a', getLabel(field), th).setAttribute('href', `#${id}`);
      const prop = ns.expand(field.getProperty());
      nsReg(prop);
      createEl('td', ns.shortenKnown(prop), tr);
      const card = field.getCardinality() || {};
      if (card.min > 0) {
        createEl(
          'td',
          i18n.localize(specNLS, 'levelMandatory', {}).toLowerCase(),
          tr
        );
      } else if (card.pref > 0) {
        createEl(
          'td',
          i18n.localize(specNLS, 'levelRecommended', {}).toLowerCase(),
          tr
        );
      } else {
        createEl(
          'td',
          i18n.localize(specNLS, 'levelOptional', {}).toLowerCase(),
          tr
        );
      }
      renderFieldDetails(field, node, extras, getHREF);
    }
  }
};

const renderForm = (item, node, toc, id, extras, getHREF) => {
  const tocLi = renderFormHeader(item, node, toc, id);
  const tocOl = createEl('ol', null, tocLi);
  const rdftype = getConstrType(item);
  if (rdftype) {
    createEl('strong', `${i18n.localize(specNLS, 'class', {})}: `, node);
    const a = createEl('a', rdftype, node);
    a.href = getHREF ? getHREF(rdftype, 'class') : rdftype;
    a.innerText = ns.shortenKnown(rdftype);
    nsReg(rdftype);
  }
  const desc = item.getDescription();
  if (desc) {
    createEl('p', desc, node, true);
  }
  const children = item.getChildren();
  if (children.length === 0) {
    createEl('p', i18n.localize(specNLS, 'noProperties', {}), node);
    return;
  }
  const table = createEl('table', null, node);
  table.classList.add('data');
  createEl('colgroup', null, table).classList.add('header');
  createEl('colgroup', null, table).setAttribute('span', 2);
  const thead = createEl('thead', null, table);
  const htr = createEl('tr', null, thead);
  createEl('td', null, htr);
  createEl('th', i18n.localize(specNLS, 'fieldTableHeaderProperty', {}), htr);
  createEl('th', i18n.localize(specNLS, 'fieldTableHeaderLevel', {}), htr);
  const tbody = createEl('tbody', null, table);

  children.forEach((field) => {
    renderField(item, node, field, tbody, tocOl, extras, getHREF);
  });
};

const renderForms = (main, supportive, extras, getHREF) => {
  indexForms(supportive.items, true);
  indexForms(main.items);
  chapter = '3';
  main.items.forEach((item) =>
    renderForm(item, main.node, main.nodeToc, undefined, extras, getHREF)
  );
  initHeaderCounters();
  chapter = '4';
  inline.forEach((obj) =>
    renderForm(
      obj.item,
      supportive.node,
      supportive.nodeToc,
      obj.id,
      extras,
      getHREF
    )
  );
};

export { renderForms };
