import { namespaces } from '@entryscape/rdfjson';

export const NAMESPACE_SHACL = 'http://www.w3.org/ns/shacl#';
export const NAMESPACE_SHACL_AP = 'http://exampel.com/Profile#';
export const NAMESPACE_PROF = 'http://www.w3.org/ns/dx/prof/';
export const NAMESPACE_RDFORMS = 'https://rdforms.org/terms/';
export const NAMESPACE_INSPEC = 'https://w3id.org/inspec/datavoc/';

namespaces.add('sh', NAMESPACE_SHACL);
namespaces.add('shap', NAMESPACE_SHACL_AP);
namespaces.add('prof', NAMESPACE_PROF);
namespaces.add('rdforms', NAMESPACE_RDFORMS);
namespaces.add('inspec', NAMESPACE_INSPEC);

export const RDF_TYPE_PROPERTYSHAPE = namespaces.expand('sh:PropertyShape');
export const RDF_TYPE_NODESHAPE = namespaces.expand('sh:NodeShape');
export const RDF_TYPE_PROFILE = namespaces.expand('prof:Profile');
export const RDF_TYPE_ONTOLOGY = namespaces.expand('owl:Ontology');
export const SH_IRI = namespaces.expand('sh:IRI');
export const SH_LITERAL = namespaces.expand('sh:Literal');
export const SH_BLANK_OR_IRI = namespaces.expand('sh:BlankNodeOrIRI');
export const SH_BLANK = namespaces.expand('sh:BlankNode');
export const SH_TARGET_CLASS = namespaces.expand('sh:targetClass');
export const SH_CLASS = namespaces.expand('sh:class');
export const SH_DECLARE = namespaces.expand('sh:declare');
export const SH_PREFIX = namespaces.expand('sh:prefix');
export const SH_NAMESPACE = namespaces.expand('sh:namespace');
export const RDF_LANGSTRING = namespaces.expand('rdf:langString');
export const SKOS_SCOPENOTE = namespaces.expand('skos:scopeNote');
export const RDF_TYPE_PROFILEFORM = namespaces.expand('rdforms:ProfileForm');

export const RECOMMENDED_PROPERTY = namespaces.expand('shap:recommended');
